#!/usr/bin/env bash
# grafana/grafana 10.5.15 - base variant: static-passwords
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/grafana-grafana-10-5-15.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the static-passwords base variant into ./grafana-grafana-10-5-15-static-passwords"
cub installer setup --pull oci://ghcr.io/confighub/packages/grafana:v10.5.15@sha256:6b4a5d1ebf104fb5214504017f3bea306aa604e97aa2b7830248da821232c3c3 --base static-passwords --work-dir ./grafana-grafana-10-5-15-static-passwords --non-interactive --namespace grafana

say "Read what was rendered; nothing has touched the cluster yet"
ls ./grafana-grafana-10-5-15-static-passwords/out/manifests

say "Ensure the grafana namespace exists"
kubectl create namespace grafana --dry-run=client -o yaml | kubectl apply -f -

if [ -d ./grafana-grafana-10-5-15-static-passwords/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./grafana-grafana-10-5-15-static-passwords/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./grafana-grafana-10-5-15-static-passwords/out/manifests

say "Done. The cluster received exactly the files in ./grafana-grafana-10-5-15-static-passwords/out."
